mapper.select:
SELECT * FROM ( SELECT ROW_NUMBER() OVER (ORDER BY B.FRST_REG_DT DESC) AS rnum, B.BOARD_ID, B.BOARD_TYPE_CD, B.BOARD_SJ, B.BOARD_CN, B.FRST_RGTR_ID, B.FRST_REG_DT, B.LAST_MDFR_DT, B.BOARD_ATCH_FILE_ID, B.DEPT_CD, B.PROJ_ID, B.IMPRTNT_YN, B.CMNT_USE_YN, B.VIEW_CNT FROM tb_board B WHERE 1 = 1 AND ( #{global} = 1 OR B.BOARD_TYPE_CD IN ('FREE', 'ANON', 'NOTICE') OR B.FRST_RGTR_ID = #{currentEmpId} OR B.DEPT_CD = #{myDeptCd}
OR B.DEPT_CD IN
#{deptCd}
OR TO_CHAR(B.PROJ_ID) IN
#{projId}
)
AND ( B.BOARD_SJ LIKE '%' || #{condition.keyword} || '%' OR B.BOARD_CN LIKE '%' || #{condition.keyword} || '%' )
)
WHERE rnum > #{offset} AND rnum <= #{offset} + #{size}
